#[test]
fn test_document_streams_parse_like_jq_5608() -> Result<()> {
    for (args, stdin, expected, code) in ROWS {
        let (stdout, stderr, status) = run_jq_full(args, Some(stdin))?;
        assert_eq!(
            (stdout.trim_end(), status),
            (*expected, *code),
            "{args:?} on {stdin:?}: stderr {stderr}"
        );
    }
    Ok(())
}
